// --- mission-medals: a run's special missions as badges, not text
// (openspec/changes/mission-medals, specs/mission-medals).
//
// One medal per mission id in a run record (a bonus level met, the run
// rule). Each is composed from the hero atlas (`mission_medal_atlas.dart`,
// generated by the medal family's bake): the mission's ribbon, the shared
// medal base, the mission's accent and its emblem, stacked whole cells.
// A future mission only adds its layers to the atlas; an id the atlas
// does not know wears the generic ribbon and emblem. The mission's name is
// the medal's accessibility label and its tap tooltip, never a visible chip.
import 'dart:async';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../game/bonus/bonus_catalog.dart' show runTagLabel;
import 'mission_medal_atlas.dart';

/// The atlas image, decoded once and shared by every medal.
abstract final class MissionMedalSheet {
  static final image = ValueNotifier<ui.Image?>(null);
  static Future<void>? _loading;

  /// Starts decoding the atlas (once); medals paint their fallback until
  /// it is in.
  static Future<void> load([AssetBundle? bundle]) => _loading ??= () async {
    try {
      final data = await (bundle ?? rootBundle).load(MissionMedalAtlas.asset);
      final codec = await ui.instantiateImageCodec(data.buffer.asUint8List());
      image.value = (await codec.getNextFrame()).image;
      codec.dispose();
    } catch (_) {
      // No atlas (a test bundle, a failed fetch): the fallback stays.
    }
  }();

  /// The layers that compose [id], bottom to top, as atlas cells.
  static List<(int, int)> layers(String id) {
    final cells = MissionMedalAtlas.cells;
    return [
      ?(cells['ribbon.$id'] ?? cells['ribbon.generic']),
      ?cells['base'],
      ?cells['accent.$id'],
      ?(cells['emblem.$id'] ?? cells['emblem.generic']),
    ];
  }

  /// The atlas knows this mission (its own ribbon and emblem).
  static bool knows(String id) =>
      MissionMedalAtlas.cells.containsKey('ribbon.$id') &&
      MissionMedalAtlas.cells.containsKey('emblem.$id');
}

/// One mission's medal, [size] logical pixels tall.
class MissionMedal extends StatelessWidget {
  const MissionMedal({super.key, required this.id, this.size = 24});
  final String id;
  final double size;

  static double get aspect =>
      MissionMedalAtlas.cellWidth / MissionMedalAtlas.cellHeight;

  @override
  Widget build(BuildContext context) {
    unawaited(MissionMedalSheet.load());
    final name = runTagLabel(id);
    return Tooltip(
      message: name,
      triggerMode: TooltipTriggerMode.tap,
      excludeFromSemantics: true,
      child: Semantics(
        label: '$name mission medal',
        image: true,
        child: ValueListenableBuilder<ui.Image?>(
          valueListenable: MissionMedalSheet.image,
          builder: (context, image, _) => CustomPaint(
            key: ValueKey('mission-medal-$id'),
            size: Size(size * aspect, size),
            painter: MissionMedalPainter(id, image),
          ),
        ),
      ),
    );
  }
}

/// A row of a record's mission medals (none: an empty box).
class MissionMedals extends StatelessWidget {
  const MissionMedals({
    super.key,
    required this.ids,
    this.size = 24,
    this.gap = 3,
  });
  final List<String> ids;
  final double size, gap;

  @override
  Widget build(BuildContext context) => Row(
    mainAxisSize: MainAxisSize.min,
    children: [
      for (var i = 0; i < ids.length; i++) ...[
        if (i > 0) SizedBox(width: gap),
        MissionMedal(id: ids[i], size: size),
      ],
    ],
  );
}

class MissionMedalPainter extends CustomPainter {
  const MissionMedalPainter(this.id, this.image);
  final String id;
  final ui.Image? image;

  @override
  void paint(Canvas canvas, Size size) {
    final img = image;
    if (img == null) {
      _fallback(canvas, size);
      return;
    }
    const w = MissionMedalAtlas.cellWidth, h = MissionMedalAtlas.cellHeight;
    final dst = Offset.zero & size;
    final paint = Paint()
      ..filterQuality = FilterQuality.medium
      ..isAntiAlias = true;
    for (final (col, row) in MissionMedalSheet.layers(id)) {
      canvas.drawImageRect(
        img,
        Rect.fromLTWH(col * w * 1.0, row * h * 1.0, w * 1.0, h * 1.0),
        dst,
        paint,
      );
    }
  }

  /// Before the atlas is decoded: a ribbon in the mission's colours over
  /// a plain gold disc (the same footprint, so nothing shifts).
  void _fallback(Canvas canvas, Size size) {
    final (a, b) = fallbackColors[id] ?? (const Color(0xFF8AA1B8), gold);
    final w = size.width, h = size.height;
    final ribbon = Path()
      ..moveTo(w * .28, 0)
      ..lineTo(w * .72, 0)
      ..lineTo(w * .62, h * .5)
      ..lineTo(w * .38, h * .5)
      ..close();
    canvas.drawPath(ribbon, Paint()..color = a);
    canvas.drawRect(
      Rect.fromLTWH(w * .46, 0, w * .08, h * .5),
      Paint()..color = b,
    );
    final c = Offset(w / 2, h * .66);
    final r = w * .34;
    canvas.drawCircle(c, r, Paint()..color = gold);
    canvas.drawCircle(c, r * .7, Paint()..color = const Color(0xFF101827));
    canvas.drawCircle(c, r * .38, Paint()..color = a);
  }

  static const gold = Color(0xFFF4CA79);

  /// Ribbon and stripe colours per mission (the fallback only; the atlas
  /// carries the real art).
  static const fallbackColors = <String, (Color, Color)>{
    'supplyRun': (Color(0xFF3FBF9A), Color(0xFFFFD27A)),
    'stormfront': (Color(0xFF5B4FC4), Color(0xFFE4DCFF)),
    'crosswind': (Color(0xFF4F8FB8), Color(0xFFFF8A4C)), // --- crosswind
    'noShield': (Color(0xFFC4473F), Color(0xFF70F5D5)),
    'spreadOnly': (Color(0xFF2E8FD0), Color(0xFFFFFFFF)),
    'heavyOrdnance': (Color(0xFFD9822B), Color(0xFF3A2410)),
  };

  @override
  bool shouldRepaint(MissionMedalPainter old) =>
      id != old.id || image != old.image;
}
